INSERT [dbo].[MailTemplates] ([MailTemplateId], [Heading], [Subject], [Description], [MailType], [UpdatedBy], [UpdatedTime]) VALUES (6, N'Admin Member Registration Details ', N'Member Registration Details - Dallas Area Telangana Association (DATA)', N'<table border="0" cellpadding="0" cellspacing="0" style="background: linear-gradient(0deg, #fff 0%, #F1EAFF 100%); padding: 20px 0;font-family: Poppins,sans-serif;" width="100%">
