INSERT [dbo].[PageDetails] ([PageDetailId], [Heading], [Description], [PageUrl], [DocumentUrl], [Target], [PageTitle], [MetaDescription], [MetaKeywords], [TopLine], [IsActive], [UpdatedBy], [UpdatedDate], [InsertedBy], [InsertedDate], [OtherUrl], [AddPage]) VALUES (10436, N'President Message In Home', N'<div class="main-btns">
	<div class="president_msg">
		<h4>
			President Message</h4>
		<img alt="" src="Content/User/images/data-president.jpg" />
		<h5>
			Hari Dornala</h5>
		<h6>
			President&ndash;Data</h6>
		<p>
			Lorem ipsum dolor sit amet consectetur adipisicing elit. Repudiandae iste a, dicta at cumque architecto animi amet voluptas autem suscipit<a href="p/president’s-message" style="color:#f66c0c;">...ReadMore</a></p>
	</div>
</div>
', N'president-message-in-home', N'', N'', N'', N'', N'', N'', 1, N'support@arjunweb.in', CAST(N'2025-05-30T15:38:19.130' AS DateTime), N'info@association.org', CAST(N'2023-06-23T06:30:17.400' AS DateTime), N'', N'')
